// ─── File: MeshDemo.java ───
// Runnable demo: sidecars apply mTLS, retry, timeout, metrics, and canary routing.
package com.bank.mesh;

import java.util.*;
import java.util.logging.*;

public class MeshDemo {

    private static final Logger log = Logger.getLogger("Mesh");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Control plane configures policy; sidecars read it — app code unchanged.
        ControlPlane controlPlane = new ControlPlane();
        controlPlane.setCanary("transfer-service", 95, 5);   // v1=95%, v2=5%

        Sidecar sidecar = new Sidecar(controlPlane);
        TransferServiceV1 v1 = new TransferServiceV1();
        TransferServiceV2 v2 = new TransferServiceV2();

        // 10 calls hop through the sidecar: mTLS + retry + timeout + metrics + canary.
        int v1Count = 0, v2Count = 0;
        for (int i = 1; i <= 10; i++) {
            String version = controlPlane.pickVersion("transfer-service");
            String result = sidecar.call("transfer-service", version,
                    () -> version.equals("v2") ? v2.transfer() : v1.transfer());
            if (version.equals("v2")) v2Count++; else v1Count++;
            log.fine(() -> "call routed to " + version + " → " + result);
        }
        final int fv1 = v1Count, fv2 = v2Count;
        log.info(() -> "Canary split observed: v1=" + fv1 + " v2=" + fv2 + " (target 95/5)");
        controlPlane.printMetrics();
    }
}

// ─── dataplane/Sidecar.java (Envoy-style proxy: intercepts every call) ───
class Sidecar {
    private static final Logger log = Logger.getLogger("Mesh");
    private final ControlPlane controlPlane;
    Sidecar(ControlPlane controlPlane) { this.controlPlane = controlPlane; }

    String call(String service, String version, java.util.function.Supplier<String> upstream) {
        // 1) mutual TLS (transparent — app does a plain call)
        log.fine(() -> "[sidecar] mTLS handshake to " + service + "/" + version);
        long start = System.currentTimeMillis();
        int attempts = controlPlane.retryAttempts();
        RuntimeException last = null;
        for (int i = 1; i <= attempts; i++) {   // 2) retry policy
            try {
                String r = upstream.get();       // 3) timeout would wrap this in real Envoy
                controlPlane.recordMetric(service, true, System.currentTimeMillis() - start);
                return r;
            } catch (RuntimeException e) { last = e; log.warning("[sidecar] retry " + i); }
        }
        controlPlane.recordMetric(service, false, System.currentTimeMillis() - start);  // 4) metrics
        throw last;
    }
}

// ─── controlplane/ControlPlane.java (istiod-style: policy + discovery + metrics) ───
class ControlPlane {
    private static final Logger log = Logger.getLogger("Mesh");
    private int v1Weight = 100, v2Weight = 0;
    private int retries = 2;
    private int requests = 0, errors = 0; private long totalLatency = 0;
    private final Random rnd = new Random(42);

    void setCanary(String service, int w1, int w2) {
        this.v1Weight = w1; this.v2Weight = w2;
        log.info(() -> "control plane: canary " + service + " v1=" + w1 + "% v2=" + w2 + "%");
    }
    String pickVersion(String service) { return rnd.nextInt(100) < v2Weight ? "v2" : "v1"; }
    int retryAttempts() { return retries; }
    void recordMetric(String service, boolean ok, long latencyMs) {
        requests++; if (!ok) errors++; totalLatency += latencyMs;
    }
    void printMetrics() {
        log.info(() -> "golden signals → requests=" + requests + " errors=" + errors
                + " avgLatencyMs=" + (requests == 0 ? 0 : totalLatency / requests));
    }
}

// ─── service/TransferServiceV1.java (plain business logic — knows nothing of the mesh) ───
class TransferServiceV1 { String transfer() { return "v1-settled"; } }

// ─── service/TransferServiceV2.java ───
class TransferServiceV2 { String transfer() { return "v2-settled-faster"; } }

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
